    precious: [],
    glossary: [],
    notebookPages: [],
    notebookDraft: null,
    notebookLoaded: false,

    diaryDailies: [],
    diaryRewriting: '',
    diaryWeeklies: [],
    diaryExpanded: {},
    diaryMode: 'daily',
    diaryPick: '',
    diaryReading: false,

    worldItems: [],
    worldSelection: {},
    worldQuery: '',
